import vm from 'node:vm';
import {fileURLToPath} from 'node:url';
const root=resolve(fileURLToPath(new URL('..',import.meta.url))),read=name=>readFileSync(join(root,name),'utf8'),manifest=JSON.parse(read('manifest.json')),pkg=JSON.parse(read('package.json')),lock=JSON.parse(read('package-lock.json')),versions=JSON.parse(read('versions.json'));
const assert=(ok,message)=>{if(!ok)throw Error(message);},semver=/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/u;
const prereleases=JSON.parse(read('.github/prereleases.json')),prerelease=/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)-(?:alpha|beta|rc)\.[1-9]\d*$/u;assert(Array.isArray(prereleases)&&prereleases.every(version=>typeof version==='string'&&prerelease.test(version)),'Ungültige Vorabversionsliste.');
for(const key of ['id','name','version','minAppVersion','description','author'])assert(typeof manifest[key]==='string'&&manifest[key].trim(),`manifest.json: ${key} fehlt.`);
assert(/^[a-z][a-z-]*$/u.test(manifest.id)&&!manifest.id.includes('obsidian')&&!manifest.id.endsWith('plugin'),'Ungültige Obsidian-Plugin-ID.');
assert(/^[A-Za-z0-9 ()+-]+$/u.test(manifest.name)&&!/obsidian|plugin/iu.test(manifest.name),'Ungültiger Plugin-Name.');
assert(semver.test(manifest.version)&&semver.test(manifest.minAppVersion),'Versionen müssen dem Format x.y.z entsprechen.');
assert(typeof manifest.isDesktopOnly==='boolean','isDesktopOnly muss ausdrücklich gesetzt sein.');
assert(manifest.version===pkg.version&&pkg.version===lock.version&&pkg.version===lock.packages[''].version,'Manifest, Paket und Lockdatei haben verschiedene Versionen.');
assert(versions[manifest.version]===manifest.minAppVersion,'versions.json passt nicht zum Release.');
const tag=process.env.RELEASE_TAG??(process.env.GITHUB_REF_TYPE==='tag'?process.env.GITHUB_REF_NAME:undefined),releaseVersion=tag??manifest.version,isPrerelease=prereleases.includes(releaseVersion);if(tag)assert(tag===manifest.version||isPrerelease&&tag.startsWith(manifest.version+'-'),'Git-Tag und Manifest-Version stimmen nicht überein. Vorabversionen benötigen einen registrierten Suffix wie -beta.2; kein v-Präfix verwenden.');
for(const file of ['README.md','LICENSE','CHANGELOG.md','main.js','styles.css'])assert(existsSync(join(root,file)),`Release-Datei fehlt: ${file}`);
const main=read('main.js');assert(main.length>10000,'main.js ist kein vollständiges Bundle.');assert(!main.includes('sourceMappingURL=data:'),'Produktionsbundle enthält eine Inline-Sourcemap.');assert(!main.includes(root),'Produktionsbundle enthält einen lokalen Entwicklungspfad.');new vm.Script(main,{filename:'main.js'});
const files=['main.js','manifest.json','styles.css'],directory=join(root,'dist',releaseVersion);mkdirSync(directory,{recursive:true});
const expected=[...files,'SHA256SUMS.txt'];assert(readdirSync(directory).every(file=>expected.includes(file)),'Unerwartete Dateien im Release-Ordner.');
const checksums=files.map(file=>{const bytes=readFileSync(join(root,file));assert(bytes.length>0,`${file} ist leer.`);copyFileSync(join(root,file),join(directory,file));return createHash('sha256').update(bytes).digest('hex')+'  '+file;});
writeFileSync(join(directory,'SHA256SUMS.txt'),checksums.join('\n')+'\n');console.log(JSON.stringify({version:manifest.version,prerelease:isPrerelease,id:manifest.id,minAppVersion:manifest.minAppVersion,tag:tag??'nicht angefordert',files:expected,checks:'Manifest, Versionen, Tag, Bundle-Syntax, Quellpfade und individuelle Assets geprüft',directory:'dist/'+releaseVersion},null,2));
